static auto read_probe_list(const std::string& path) -> std::vector<uint16_t>
{
  std::ifstream pf{path};
  if (!pf)
    throw std::runtime_error("--probe: cannot open " + path);
  std::vector<uint16_t> addrs;
  for (std::string line; std::getline(pf, line);) {
    const auto b = line.find_first_not_of(" \t\r");
    if (b == std::string::npos || line[b] == '#') continue;
    addrs.push_back(
      static_cast<uint16_t>(std::stoul(line.substr(b), nullptr, 16)));
  }
  return addrs;
}

static void emit_probe_csv(
  const std::vector<std::pair<uint16_t, std::optional<uint64_t>>>& results)
{
  for (const auto& r: results) {
    if (r.second)
      fmt::print("0x{:03X},yes,0x{:016x}\n", r.first, *r.second);
    else
      fmt::print("0x{:03X},no,-\n", r.first);
  }
}

extern "C" auto sc_main(const int argc, char* argv[]) -> int
try {
  spdlog::set_default_logger(spdlog::stderr_color_mt("stderr_logger"));
  spdlog::set_pattern("[%^%l%$] %v");

